```kotlin
class ResourceCycleDetector : Detector(), XmlScanner {
    // Graph: resource -> set of resources it depends on
    private val dependencies = mutableMapOf<String, MutableSet<String>>()
    // Locations for reporting
    private val locations = mutableMapOf<String, Location>()

    override fun getApplicableElements(): Collection<String>? = XmlScanner.ALL

    override fun visitElement(context: XmlContext, element: Element) {
        val folderType = context.resourceFolderType ?: return
        val tagName = element.tagName

        // Determine the defined resource key (type/name)
        var definedKey: String? = null
        if (folderType == ResourceFolderType.VALUES) {
            val nameAttr = element.getAttributeNode("name")
            if (nameAttr != null) {
                val name = nameAttr.value
                val type = if (tagName == "item") element.getAttribute("type") else tagName
                if (type.isNotBlank() && name.isNotBlank()) {
                    definedKey = "$type/$name"
                    locations[definedKey] = context.getLocation(nameAttr)
                }
            }
        } else if (folderType == ResourceFolderType.LAYOUT) {
            // Layouts are defined by file name, but includes reference other layouts
            // We might not need to track layout definitions for cycles unless include cycles matter.
            // Actually, layout files can include each other.
            // The file itself defines a layout resource.
            val fileName = context.file.nameWithoutExtension
            definedKey = "layout/$fileName"
            locations[definedKey] = context.getLocation(element) // or name location?
        } else if (folderType == ResourceFolderType.DRAWABLE || folderType == ResourceFolderType.COLOR || folderType == ResourceFolderType.FONT || folderType == ResourceFolderType.MIPMAP) {
            val fileName = context.file.nameWithoutExtension
            val type = folderType.getName()
            definedKey = "$type/$fileName"
            locations[definedKey] = context.getLocation(element)
        }

        if (definedKey != null) {
            dependencies.getOrPut(definedKey) { mutableSetOf() }
        }

        // Extract references
        val refs = mutableSetOf<String>()

        // Handle style parent
        if (tagName == "style") {
            val parentAttr = element.getAttributeNode("parent")
            if (parentAttr != null) {
                val parentVal = parentAttr.value
                if (parentVal.isNotBlank()) {
                    val parentKey = parseResourceRef(parentVal, "style")
                    if (parentKey != null) refs.add(parentKey)
                }
            } else {
                // Implied parent
                val nameAttr = element.getAttributeNode("name")
                if (nameAttr != null) {
                    val name = nameAttr.value
                    val dotIndex = name.lastIndexOf('.')
                    if (dotIndex > 0) {
                        val impliedParent = name.substring(0, dotIndex)
                        refs.add("style/$impliedParent")
                    }
                }
            }
        }

        // Handle include layout
        if (tagName == "include") {
            val layoutAttr = element.getAttributeNode("layout")
            if (layoutAttr != null) {
                val ref = parseResourceRef(layoutAttr.value, "layout")
                if (ref != null) refs.add(ref)
            }
        }

        // Scan all attributes for references
        val attrs = element.attributes
        for (i in 0 until attrs.length) {
            val attr = attrs.item(i)
            val value = attr.value
            if (value.contains('@') || value.contains('?')) {
                extractRefsFromString(value, refs)
            }
        }

        // Scan text content
        val text = element.textContent
        if (text != null && (text.contains('@') || text.contains('?'))) {
            extractRefsFromString(text, refs)
        }

        if (definedKey != null && refs.isNotEmpty()) {
            dependencies[definedKey]!!.addAll(refs)
        }
    }

    private fun parseResourceRef(value: String, defaultType: String): String? {
        val clean = value.removePrefix("@").removePrefix("?").removePrefix("+")
        // handle android: prefix
        val parts = clean.split('/')
        if (parts.size == 2) {
            val type = parts[0].substringAfter(':')
            return "$type/${parts[1]}"
        }
        // If no slash, it might be a style parent reference like "Theme.AppCompat"
        // In that case, assume defaultType
        return "$defaultType/$clean"
    }

    private fun extractRefsFromString(value: String, refs: MutableSet<String>) {
        val regex = Regex("[@?]\\+?([\\w:]+)/([\\w.]+)")
        regex.findAll(value).forEach { match ->
            val typePart = match.groupValues[1]
            val name = match.groupValues[2]
            val type = typePart.substringAfter(':')
            if (type != "id" && type != "android") { // ignore ids and android framework refs? Actually android refs can't cycle with app refs, so safe to ignore
                refs.add("$type/$name")
            }
        }
    }
    // ...
}
```

